let activeFloor = 1;
let activeRoomIndex = null;

function renderRooms(floor) {
  const grid = document.getElementById('roomsGrid');
  const rooms = floors[floor];
  grid.innerHTML = rooms.map((r, i) => `
    <div class="room-card reveal" onclick="showRoom(${floor}, ${i})" id="room-${floor}-${i}" style="transition-delay:${i*0.05}s">
      <div class="room-number">0${i+1}</div>
      <div class="room-name">${r.name}</div>
      ${r.size ? `<div class="room-size">${r.size}</div>` : ''}
    </div>
  `).join('');
  // Re-observe
  grid.querySelectorAll('.reveal').forEach(el => observer.observe(el));
}

function switchFloor(floor, btn) {
  activeFloor = floor;
  activeRoomIndex = null;
  document.getElementById('roomDetail').classList.remove('visible');
  document.querySelectorAll('.floor-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  renderRooms(floor);
}

function showRoom(floor, idx) {
  const room = floors[floor][idx];
  // Update active state
  document.querySelectorAll('.room-card').forEach(c => c.classList.remove('active'));
  document.getElementById(`room-${floor}-${idx}`)?.classList.add('active');

  // Show detail
  document.getElementById('detailTitle').textContent = room.name;
  document.getElementById('detailDesc').textContent = room.desc;
  document.getElementById('detailSize').textContent = room.size || '';

  // Update photo
  const placeholder = document.getElementById('detailPlaceholder');
  const detailImg = document.getElementById('detailImg');
  if (room.img) {
    detailImg.src = room.img;
    detailImg.style.display = 'block';
    placeholder.style.display = 'none';
  } else {
    detailImg.style.display = 'none';
    placeholder.style.display = 'flex';
  }

  const detail = document.getElementById('roomDetail');
  detail.classList.add('visible');
  setTimeout(() => detail.scrollIntoView({ behavior: 'smooth', block: 'nearest' }), 100);
}

